//
//  Unlocks source\Resources\toolbox.enc: every tool script in one AES-256 blob
//  that lives inside the panel executable, so no .py is ever written to disk.
//
//  This file holds a SEED, never the key. The key for a payload is derived from
//  it at run time and mixed with that payload's own SHA-256:
//
//      key = PBKDF2-SHA256(seed, salt || sha256(zip), 150000, 32)
//
//  What that buys: no 32-byte key exists in the product to copy and reuse, the
//  key is different in every build, and the same seed cannot open a different
//  (or edited) payload - so patching one byte of the blob kills decryption
//  instead of yielding a valid archive.
//
//  What it does not buy: secrecy. The panel must be able to read its own tools
//  on the customer's machine, so a determined reverse engineer can always
//  recreate this derivation. It stops the casual copy, nothing more.
// ---------------------------------------------------------------------------
namespace AISuitePanel.Automation;

internal static class ToolboxKey
{
    private const int Iterations = 150000;

    private static readonly byte[] SeedParts = { 0x28, 0xB8, 0xD6, 0xF3, 0x37, 0x9F, 0xBB, 0xED, 0x20, 0xD1, 0x31, 0x0A, 0xE9, 0xC5, 0x6E, 0xEE, 0xC0, 0x66, 0x5F, 0x76, 0x36, 0x4C, 0x20, 0x91, 0x74, 0x22, 0x3B, 0x8D, 0xB8, 0x8D, 0x31, 0x27 };

    private static readonly byte[] SeedMask = { 0x34, 0xFE, 0xF6, 0x45, 0x96, 0x59, 0x73, 0xE7, 0x0C, 0x05, 0x14, 0x68, 0xF3, 0xBA, 0x96, 0x05 };

    private static readonly byte[] Salt = { 0x40, 0x36, 0x85, 0xFC, 0xD1, 0x68, 0xFA, 0x42, 0xC2, 0x62, 0xC6, 0xE0, 0x63, 0x54, 0x7B, 0x56 };

    /// <summary>
    /// The AES-256 key for one payload. <paramref name="payloadSha"/> is read
    /// out of that payload's header, so a key can never outlive the blob it was
    /// made for.
    /// </summary>
    internal static byte[] Derive(byte[] payloadSha)
    {
        var seed = new byte[SeedParts.Length];
        for (int i = 0; i < seed.Length; i++)
        {
            seed[i] = (byte)(SeedParts[i] ^ SeedMask[i % SeedMask.Length]);
        }

        var salt = new byte[Salt.Length + payloadSha.Length];
        Buffer.BlockCopy(Salt, 0, salt, 0, Salt.Length);
        Buffer.BlockCopy(payloadSha, 0, salt, Salt.Length, payloadSha.Length);

        using var kdf = new System.Security.Cryptography.Rfc2898DeriveBytes(
            seed, salt, Iterations, System.Security.Cryptography.HashAlgorithmName.SHA256);
        var key = kdf.GetBytes(32);
        Array.Clear(seed, 0, seed.Length);
        return key;
    }
}
